-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "DPS in mischia"
L["rm.era.warrior.dps.Description"] = "Livelli 1–60, Armi e Furia, e ogni guerriero fuori dalla Postura da Difesa, anche sui reami Hardcore e Self-Found; costruita a partire da simulatore, Icy Veins e Wowhead. Carica per ingaggiare, Intercettazione su un bersaglio lontano, Turbine (Schianto del Tuono prima di averlo appreso) contro tre o più nemici che ti combattono, poi Esecuzione per prima sotto il 20%, Incrinatura fino a cinque sui boss senza Smantella Armatura, Sete di Sangue, Assalto Mortale, Contusione subito dopo un colpo con Contusione Migliorata (impostata per un'arma a due mani; cambiala in un duplicato), Turbine conservando ira per il tuo colpo principale, Dominazione, Squartamento finché non hai appreso il tuo colpo principale, Incrinatura sui bersagli in salute e Azzoppamento vicino al massimo di ira. Promemoria: Urlo di Battaglia, Assalto Eroico da 40 di ira (20 durante il livellamento), Fendente sui gruppi di nemici, Rabbia del Sangue, Assalti Fendenti, Desiderio di Morte (sui boss: i loro ultimi 30 secondi), Avventatezza con Desiderio di Morte, Pugno Diversivo o Sfondamento di Scudo. Urlo Intimidatorio e Rappresaglia sono elencati ma disattivati per le emergenze Hardcore; il cambio di postura resta a te."
L["rm.era.warrior.protection.Name"] = "Difensore"
L["rm.era.warrior.protection.Description"] = "Scelta ogni volta che sei in Postura da Difesa (Protezione, Furia-Protezione o difensore con arma a due mani); costruita a partire da Icy Veins e MaxDps. Contro quattro o più nemici: Urlo Demoralizzante e Urlo di Battaglia per la minaccia. Poi Rivincita, Colpo di Scudo, Sete di Sangue, Incrinatura fino a cinque, Urlo Demoralizzante sulle élite, Incrinatura come riempitivo, e Squartamento prima di Colpo di Scudo o Sete di Sangue. Colpo di Scudo e Scudo Saldo solo con uno scudo equipaggiato. Promemoria: Urlo di Battaglia, Scudo Saldo mentre il bersaglio ti colpisce, Rabbia del Sangue, Assalto Eroico e Fendente da 50 di ira, Sfondamento di Scudo, Ultima Difesa. Provocazione, Muro di Scudi e Desiderio di Morte sono elencati ma disattivati; la Postura da Battaglia per Esecuzione (subentra la rotazione integrata da DPS) e Urlo di Sfida restano a te."
L["rm.era.warrior.protection.icyveins.Name"] = "Difensore, minaccia con Urlo di Battaglia (Icy Veins)"
L["rm.era.warrior.protection.icyveins.Description"] = "Il ruolo da difensore \"senza Incrinatura\" di Icy Veins per i gruppi in cui quattro o più giocatori sentono il tuo urlo (da Urlo di Battaglia della Fase 5 in poi), un'alternativa alla rotazione integrata consigliata da difensore, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Urlo Demoralizzante sempre attivo, Rivincita, Colpo di Scudo o Sete di Sangue, poi Urlo di Battaglia come riempitivo per la minaccia invece di Incrinatura; Colpo di Scudo e Scudo Saldo solo con uno scudo equipaggiato. Stessi promemoria del difensore consigliato; torna a Incrinatura quando ti concentri su un solo bersaglio in mezzo alla folla."
L["rm.forever.warrior.dps.Name"] = "Armi e Furia (Icy Veins)"
L["rm.forever.warrior.dps.Description"] = "Armi e Furia in mischia dal livello 1 al 60, e la scelta predefinita per qualsiasi guerriero fuori dalla Postura Difensiva. Su Forever l'ira è scarsa e nascosta agli addon, quindi la accumula spendendola per qualsiasi altra cosa solo mentre Assalto Mortale o Sete di Sangue sono in recupero: Carica per ingaggiare, Frenesia di Vittoria, Intercettazione, Esecuzione (nel suo raggio d'azione) su élite, boss o in gruppo, Turbine o Schianto del Tuono, Urlo Demoralizzante e Contusione contro i gruppi, Colpo Trafiggente su Giganti e Dragoidi, Squartamento fino a Sete di Sangue, Dominazione, Assalto Mortale, Sete di Sangue, poi Turbine, Contusione da fermo e due Spaccarmatura (cinque sulle élite). Promemoria: Urlo di Battaglia, Ira Sanguinaria, l'interruzione, Assalto Eroico mentre l'attacco principale è in recupero, Fendente contro i gruppi, Colpi Ampi, Desiderio di Morte e Furia del Berserker; Avventatezza e Rappresaglia sono elencate ma disattivate. Restano a te: il cambio di postura, Azzoppamento e i consumabili."
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "Armi e Furia, spendi l'ira (Warcraft Tavern)"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "L'elenco di Warcraft Tavern per gruppi e incursioni che spende sempre l'ira: prima cinque Spaccarmatura, Esecuzione sopra ogni altra cosa sotto il 20%, Dominazione, Squartamento fino a Sete di Sangue, Assalto Mortale, Sete di Sangue, Turbine, Colpo Trafiggente appena pronto, Contusione una volta preso Contusione Migliorata; Assalto Eroico o Fendente ogni volta che te lo puoi permettere (su Forever l'ira è nascosta, quindi non c'è alcuna soglia di 60 di ira né Azzoppamento con ira in eccesso), Avventatezza appena pronta insieme a Desiderio di Morte. Sceglila al posto della rotazione integrata di Icy Veins se giochi in gruppo e non devi conservare ira tra un ingaggio e l'altro. Un'alternativa alla rotazione integrata consigliata DPS in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.forever.warrior.protection.Name"] = "Protezione (Icy Veins)"
L["rm.forever.warrior.protection.Description"] = "Ruolo da difensore ogni volta che sei in Postura Difensiva, dal livello 10 al 60. Carica per ingaggiare (in Postura Difensiva una volta che hai Avanguardia), Frenesia di Vittoria, e contro due o più nemici Schianto del Tuono appena pronto, Urlo Demoralizzante, Colpo di Scudo, Rivincita e Squartamento. Contro un solo bersaglio: Colpo di Scudo, Rivincita, Urlo Demoralizzante, Squartamento, Spaccarmatura (cinque sulle élite) e Schianto del Tuono sui bersagli pericolosi. Promemoria: Urlo di Battaglia, Ira Sanguinaria, Botta di Scudo, Scudo Saldo mentre tieni il bersaglio, Assalto Eroico mentre Colpo di Scudo e Rivincita sono entrambi in recupero, Fendente contro i gruppi; Provocazione e Muro di Scudi sono elencati ma disattivati. Su Forever ira, salute e mana del bersaglio sono nascosti agli addon, quindi le soglie di ira, i nemici incantatori e Ultima Difesa sono una tua scelta. Restano a te: passare a Postura da Battaglia per caricare prima di Avanguardia, provocare gli altri nemici e raccogliere quelli liberi."
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "Protezione, penalità sempre attive (Warcraft Tavern)"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "L'ordine da difensore di Warcraft Tavern: prima Schianto del Tuono, Urlo Demoralizzante e cinque Spaccarmatura mantenuti su ogni bersaglio, poi Rivincita, Squartamento e per ultimo Colpo di Scudo, con Assalto Eroico o Fendente ogni volta che te lo puoi permettere (su Forever l'ira è nascosta, quindi non c'è alcuna soglia di 60 di ira). Nessun promemoria per Scudo Saldo o abilità difensive. Sceglila al posto della rotazione integrata da difensore di Icy Veins se preferisci mantenere prima le penalità. Un'alternativa alla rotazione integrata consigliata Protezione, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.mop.warrior.arms.Name"] = "Consigliata"
L["rm.mop.warrior.arms.Description"] = "Consigliata per Armi dal livello 10 al 90, scelta nella specializzazione Armi. Carica per aprire, e di nuovo per l'ira quando ti allontani. Colpo del Colosso ogni volta che manca o sta per finire, Assalto Mortale, Dardo della Tempesta nella finestra di Colpo del Colosso, Ruggito del Drago e Tempesta di Lame al di fuori di essa. Sotto il 20% di salute del bersaglio: Esecuzione nella finestra, a 100 di ira o per mantenere Esecuzione Improvvisa, Dominazione con Sapore del Sangue. Altrimenti Contusione nella finestra, Dominazione a quattro cumuli, Contusione a 100 di ira, Dominazione, Contusione. Con due o più nemici che ti combattono si aggiungono Assalti Fendenti, Schianto del Tuono per Ferite Profonde, Tempesta di Lame e Ruggito del Drago. Frenesia di Vittoria sotto il 70% di salute; Urlo di Battaglia per l'ira. Promemoria: un urlo quando nessuno è attivo, Postura da Battaglia, Furia del Berserker, Avventatezza, Avatar e Bagno di Sangue con Colpo del Colosso nei combattimenti lunghi, Stendardo Teschiato, Assalto Eroico o Fendente con l'ira in avanzo, Balzo Eroico nella finestra, Pugno Diversivo, Attaccamento alla Vita e Rigenerazione Furente quando sei in difficoltà. Lancio Frantumante è elencato ma disattivato. Lasciati a te: annullare Tempesta di Lame, il cambio di postura e il posizionamento."
L["rm.mop.warrior.arms.icyveins.Name"] = "Accumulo per Colpo del Colosso (Icy Veins)"
L["rm.mop.warrior.arms.icyveins.Description"] = "Disattivata per impostazione predefinita. L'ordine Armi di Icy Veins e Wowhead: fuori dalla finestra di Colpo del Colosso usa Dominazione e Contusione solo sopra 80 di ira, conservando l'ira per la finestra invece di usare Contusione come riempitivo. Nella finestra: Assalto Mortale, Contusione, Dominazione, Lancio Eroico. Sotto il 20% di salute del bersaglio: Colpo del Colosso, Assalto Mortale, Esecuzione, Dominazione, Ruggito del Drago. Assalti Fendenti contro due nemici, una lista per i gruppi con Schianto del Tuono contro tre o più. Assalto Eroico o Fendente solo vicino al massimo di ira. Stessi promemoria della rotazione integrata Armi consigliata. Per usarla attivala e disattiva l'altra."
L["rm.mop.warrior.fury.Name"] = "Consigliata"
L["rm.mop.warrior.fury.Description"] = "Consigliata per Furia dal livello 10 al 90, scelta nella specializzazione Furia. Carica per aprire e per l'ira. Colpo del Colosso una volta accumulate due cariche di Colpo Furente (una con Avventatezza), Colpo Furente mentre la finestra si chiude, Sete di Sangue, Colpo del Colosso, Dardo della Tempesta, Ruggito del Drago fuori dalla finestra, Esecuzione qui con Furia Risoluta (armi a una mano), Tempesta di Lame mentre Sete di Sangue è in tempo di recupero, con Presa dei Titani (armi a due mani) un altro Colpo Furente fuori dalla finestra, Esecuzione, Assalto Selvaggio con Eruzione di Sangue, Colpo Furente conservando una carica per la finestra successiva, Assalto Selvaggio, Lancio Eroico, Urlo di Battaglia per l'ira. Con due o più nemici che ti combattono si aggiungono Tempesta di Lame, Ruggito del Drago, Turbine per Tritacarne e Colpi Furenti ad area. Promemoria: un urlo quando nessuno è attivo, Postura da Battaglia, Furia del Berserker per Rabbia, Avventatezza, Avatar e Bagno di Sangue con Colpo del Colosso nei combattimenti lunghi, Stendardo Teschiato, Assalto Eroico o Fendente con l'ira in avanzo, Balzo Eroico, Pugno Diversivo e abilità difensive quando sei in difficoltà. Lasciato a te: annullare Tempesta di Lame."
L["rm.mop.warrior.fury.icyveins.Name"] = "Tempi di recupero durante Colpo del Colosso (Icy Veins)"
L["rm.mop.warrior.fury.icyveins.Description"] = "Disattivata per impostazione predefinita. L'ordine Furia di Icy Veins spende prima Tempesta di Lame o Ruggito del Drago dentro la finestra di Colpo del Colosso, e mette Esecuzione prima di Sete di Sangue sotto il 20% di salute del bersaglio. Fuori dalla finestra: Colpo del Colosso, Sete di Sangue, Colpo Furente solo a due cariche, Assalto Selvaggio con Eruzione di Sangue, urlo, Assalto Selvaggio. Quattro o più nemici: Sete di Sangue per Rabbia, Turbine fino a tre cumuli di Tritacarne, Colpo Furente. Assalto Eroico o Fendente solo vicino al massimo di ira. Stessi promemoria della rotazione integrata Furia consigliata. Per usarla attivala e disattiva l'altra."
L["rm.mop.warrior.protection.Name"] = "Consigliata"
L["rm.mop.warrior.protection.Description"] = "Ruolo da difensore dal livello 10 al 90, scelta nella specializzazione Protezione. Carica o Lancio Eroico per ingaggiare. Sfondamento per mantenere tre cumuli di Armatura Indebolita su élite e boss, Ruggito del Drago, Tempesta di Lame, Onda d'Urto contro tre nemici e Schianto del Tuono appena pronto contro tre o più. Poi Rivincita per l'ultima ira che serve a Scudo Saldo, Colpo di Scudo, Rivincita con Difesa Critica, Sfondamento per Ferite Profonde, Frenesia di Vittoria sotto il 60% di salute, Rivincita, Schianto del Tuono per Colpi Indeboliti, Esecuzione, Dardo della Tempesta, un urlo per l'ira e Sfondamento (Incrinatura prima del livello 26). Promemoria: Postura da Difesa, un urlo quando nessuno è attivo, Scudo Saldo ogni volta che non è attivo, Scudo Rabbioso quando sei ferito con ira in avanzo, Assalto Eroico o Fendente con Ultimatum, Esortazione o vicino al massimo, Urlo Demoralizzante, Furia del Berserker, Rigenerazione Furente, Ultima Difesa e Muro di Scudi quando sei in difficoltà, i tuoi tempi di recupero offensivi, Pugno Diversivo. Provocazione e Balzo Eroico sono elencati ma disattivati. Lasciati a te: chi provocare, e Scudo Saldo o Scudo Rabbioso contro la magia."
L["rm.mop.warrior.unspecialized.Name"] = "Senza specializzazione"
L["rm.mop.warrior.unspecialized.Description"] = "Per i livelli da 1 a 9, o finché non scegli una specializzazione. Carica per ingaggiare, Frenesia di Vittoria, Esecuzione e Assalto Eroico quando hai 30 di ira; ti ricorda di stare in Postura da Battaglia se non sei in nessuna postura."
L["rm.retail.warrior.arms.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warrior.arms.Description"] = "Consigliata per Armi in Midnight. In combattimento il gioco ora nasconde agli addon la rabbia, Squartamento, Colpo del Colosso, i proc, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Assalto Eroico (un pulsante fondamentale che il suggerimento non usa mai), Avatar e Lancia del Campione in combattimento, Urlo di Battaglia tra un ingaggio e l'altro, Pugno Diversivo su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio), Attaccamento alla Vita ogni volta che è pronto in combattimento (la salute è nascosta su Retail, quindi decidi tu quando usarlo)."
L["rm.retail.warrior.arms.colossus.Name"] = "Colosso, riferimento (SimulationCraft)"
L["rm.retail.warrior.arms.colossus.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Colosso di SimulationCraft e Icy Veins accumula Vigore Colossale con Assalto Mortale e legge effetti benefici che Midnight nasconde in combattimento. Carica per aprire; Assalti Fendenti contro due o più; Assalto Mortale sotto cinque cumuli di Vigore Colossale; Squartamento prima di Colpo del Colosso; Impeto Devastatore; Esecuzione con due cumuli di Morte Improvvisa; Colpo del Colosso; Lancia del Campione; Demolizione durante Colpo del Colosso con Vigore Colossale; Assalto Eroico; Assalto Mortale; Esecuzione; Dominazione; Squartamento sotto i 5 secondi; Tempesta di Lame contro due o più; Contusione. Promemoria: Avatar, Attaccamento alla Vita, Urlo di Battaglia, Pugno Diversivo."
L["rm.retail.warrior.arms.slayer.Name"] = "Carnefice, riferimento (SimulationCraft)"
L["rm.retail.warrior.arms.slayer.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Carnefice di SimulationCraft, Icy Veins e Wowhead legge la rabbia, Squartamento, Colpo del Colosso, Morte Improvvisa e Opportunista, che Midnight nasconde in combattimento. Carica per aprire; Assalti Fendenti contro due o più nemici ingaggiati; Squartamento prima di Colpo del Colosso quando sta per scadere; Impeto Devastatore subito prima di Colpo del Colosso; Esecuzione con due cumuli di Morte Improvvisa; Colpo del Colosso; Tempesta di Lame durante Colpo del Colosso o Avatar; Assalto Eroico; Dominazione con due cumuli di Opportunista; Assalto Mortale; Esecuzione; Dominazione; Squartamento sotto i 5 secondi; Contusione. Promemoria: Avatar con Colpo del Colosso pronto, Attaccamento alla Vita, Urlo di Battaglia, Pugno Diversivo."
L["rm.retail.warrior.fury.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warrior.fury.Description"] = "Consigliata per Furia in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (Scatto d'Ira, Sete di Sangue, Colpo Furente, Esecuzione, Furia di Odyn e Tempesta di Lame), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Avventatezza, Avatar e Lancia del Campione in combattimento, Urlo di Battaglia tra un ingaggio e l'altro, Pugno Diversivo, Rigenerazione Furente ogni volta che è pronta in combattimento (la salute è nascosta su Retail, quindi decidi tu quando usarla)."
L["rm.retail.warrior.fury.slayer.Name"] = "Carnefice, riferimento (SimulationCraft)"
L["rm.retail.warrior.fury.slayer.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Carnefice di SimulationCraft legge l'effetto Furia, Avventatezza e Morte Improvvisa, che Midnight nasconde in combattimento; la rabbia è nascosta su Retail, quindi Scatto d'Ira aspetta solo il proprio costo. Carica per aprire; Turbine per il suo effetto benefico contro due o più nemici ingaggiati; Scatto d'Ira quando l'effetto Furia sta per finire; durante Avventatezza Scatto d'Ira, Tempesta di Lame, Esecuzione con Morte Improvvisa, Furia di Odyn; Colpo Devastante; Bagno di Sangue; Esecuzione; Furia di Odyn; Colpo Furente; Scatto d'Ira; Sete di Sangue; Turbine. Promemoria: Avventatezza, Avatar, Rigenerazione Furente, Urlo di Battaglia, Pugno Diversivo."
L["rm.retail.warrior.fury.thane.Name"] = "Thane della Montagna, riferimento (Icy Veins)"
L["rm.retail.warrior.fury.thane.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Thane della Montagna di SimulationCraft e Icy Veins alterna Boato del Tuono e legge effetti benefici che Midnight nasconde in combattimento. Carica per aprire; Turbine per il suo effetto benefico contro due o più; Scatto d'Ira quando l'effetto Furia manca o sta per finire (la rabbia è nascosta su Retail, quindi non c'è alcun Scatto d'Ira a 100 di rabbia); Bagno di Sangue durante Avventatezza; Boato del Tuono a due cumuli; Colpo Devastante; Bagno di Sangue; Scatto d'Ira durante Avventatezza; Boato del Tuono durante Avatar; Colpo Furente; Boato del Tuono; Scatto d'Ira; Sete di Sangue; Esecuzione; Furia di Odyn; Schianto del Tuono; Turbine. Stessi promemoria del riferimento Carnefice."
L["rm.retail.warrior.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warrior.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Guerriero). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Guerriero condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.warrior.protection.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warrior.protection.Description"] = "Consigliata per Protezione in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard per i tuoi danni e la minaccia, e si ferma mentre lanci o quando non hai un nemico come bersaglio. Il suggerimento non lancia mai Scudo Saldo né Insensibilità, quindi entrambi sono promemoria ogni volta che sono utilizzabili e il tuo bersaglio ti sta attaccando; il gioco nasconde la rabbia, quindi Insensibilità si illuminerà più spesso del necessario. Altri promemoria: Avatar, Urlo Demoralizzante e Lancia del Campione in combattimento, Muro di Scudi e Ultima Difesa ogni volta che sono pronti in combattimento (la salute è nascosta su Retail, quindi decidi tu quando usarli), Provocazione in gruppo quando il tuo bersaglio attacca qualcun altro, Urlo di Battaglia tra un ingaggio e l'altro, Pugno Diversivo."
L["rm.retail.warrior.protection.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.warrior.protection.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft legge Scudo Saldo, Boato del Tuono e Vigore Colossale, che Midnight nasconde in combattimento; rabbia e salute sono nascoste su Retail. Carica per aprire; Impeto Devastatore; Boato del Tuono a due cumuli; Demolizione a cinque cumuli di Vigore Colossale; Carica di Scudo; Boato del Tuono; Colpo di Scudo; Schianto del Tuono; Esecuzione; Rivincita; Sfondamento. Promemoria: Scudo Saldo quando il suo effetto benefico non è attivo e stai facendo da difensore, Insensibilità, Avatar, Urlo Demoralizzante, Lancia del Campione, Muro di Scudi e Ultima Difesa ogni volta che sono pronti in combattimento, Urlo di Battaglia, Pugno Diversivo."
L["rm.sod.warrior.dps.Name"] = "DPS in mischia (SoD)"
L["rm.sod.warrior.dps.Description"] = "Season of Discovery, livelli 1–60 con le rune man mano che le incidi: arma a due mani, due armi, Gladiatore e livellamento, e ogni guerriero della Season of Discovery fuori dalla Postura da Difesa; costruita a partire da simulatore Fase 6 e Wowhead Fase 7/8. Carica, Frenesia di Vittoria, Intercettazione, Turbine (prima Schianto del Tuono) contro due o più nemici, Contusione a tre cumuli di Contusioni a Raffica, Squartamento sempre attivo, Contusione con Impeto di Sangue (appena pronta con Tempismo Preciso inciso), Sete di Sangue, Assalto Mortale, Colpo di Scudo (con uno scudo), Dominazione; poi Assalto Lampo quando è inciso (arma a due mani), altrimenti Turbine, Colpo Furente e Sfondamento (prima Incrinatura); Esecuzione con 30 di ira o con Morte Improvvisa; Azzoppamento vicino al massimo di ira. Promemoria: Urlo di Battaglia e Urlo di Comando, Assalto Eroico da 50 di ira (sempre mentre Consumato dall'Ira ti rende furioso), Fendente, Rabbia del Sangue, Scatto d'Ira, Desiderio di Morte, Avventatezza, Assalti Fendenti, interruzioni. Furia del Berserker e il passaggio in Postura da Battaglia per Sapore del Sangue sono elencati ma disattivati."
L["rm.sod.warrior.dps.icyveins.Name"] = "DPS in mischia (SoD, Icy Veins)"
L["rm.sod.warrior.dps.icyveins.Description"] = "Le pagine Furia e Armi della Season of Discovery di Icy Veins, un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Esecuzione in cima alla priorità sotto il 20% o con Morte Improvvisa, Contusione con Impeto di Sangue, Sete di Sangue o Assalto Mortale, Turbine, Dominazione, Colpo Furente, poi Assalto Lampo e Azzoppamento solo sopra 60 di ira; niente Squartamento; Assalto Eroico solo sopra 80 di ira. Stessi promemoria della rotazione integrata consigliata."
L["rm.sod.warrior.dps.wowhead.Name"] = "Cambio di postura del Previsore di Battaglia (SoD, Wowhead)"
L["rm.sod.warrior.dps.wowhead.Description"] = "La rotazione della Fase 7/8 di Wowhead per Anima del Previsore di Battaglia o il set da sei pezzi del Tier 1 (che Rotation Master non può vedere), un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Cambi di postura per mantenere attivi gli effetti benefici della previsione, Assalto Eroico quasi sempre, poi Sete di Sangue, Contusione con Impeto di Sangue, Turbine, Colpo Furente e Azzoppamento; niente Squartamento e niente Dominazione. Verifica i tempi dei cambi in gioco prima di affidartici."
L["rm.sod.warrior.tank.Name"] = "Difensore (SoD)"
L["rm.sod.warrior.tank.Description"] = "Difensore della Season of Discovery, scelta in Postura da Difesa; costruita a partire da Wowhead Fase 8 e simulatore. Carica; contro due o più nemici Schianto del Tuono, Onda d'Urto, Colpo di Scudo, Rivincita, Turbine e Sfondamento; poi Colpo di Scudo ogni volta che Risolutezza del Difensore manca o sta per finire, Rivincita, Colpo di Scudo, Onda d'Urto, Esecuzione, Turbine a cinque cumuli di Astuzia del Gladiatore, Sfondamento (prima Incrinatura), Urlo Demoralizzante e Schianto del Tuono sulle élite, Squartamento prima di Colpo di Scudo; Colpo di Scudo e Scudo Saldo solo con uno scudo equipaggiato. Promemoria: Urlo di Battaglia e Urlo di Comando, Scudo Saldo, Assalto Eroico da 50 di ira, Fendente da 55, Rabbia del Sangue, Scatto d'Ira, Ultima Difesa, interruzioni. Provocazione, Muro di Scudi, Desiderio di Morte, Avventatezza e Rappresaglia sono elencati ma disattivati; il passaggio da Gladiatore per Esecuzione resta a te."
L["rm.tbc.warrior.dps.icyveins.Name"] = "DPS in mischia (Icy Veins)"
L["rm.tbc.warrior.dps.icyveins.Description"] = "Livelli 1–70, Armi o Furia, seguendo Icy Veins. Stesso ingaggio, promemoria e passaggi di livellamento della versione simulatore, ma con Assalto Mortale Esecuzione viene per prima, con Sete di Sangue Esecuzione viene subito dopo, Turbine segue senza trattenere l'ira e Azzoppamento solo con l'ira quasi piena. Il tempismo di Contusione, il cambio di postura e Furia del Berserker restano a te. Un'alternativa alla rotazione integrata consigliata DPS in mischia di simulatore, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.tbc.warrior.dps.simulator.Name"] = "DPS in mischia (simulatore)"
L["rm.tbc.warrior.dps.simulator.Description"] = "Livelli 1–70, Armi o Furia. Carica per ingaggiare, poi Frenesia di Vittoria, Intercettazione, Scatenamento e Turbine quando due o più nemici ti combattono (Schianto del Tuono prima di averlo appreso). Con Sete di Sangue o Assalto Mortale: quel colpo, Turbine con ira in eccesso, Esecuzione, Dominazione. Prima di averli: Turbine, Esecuzione, Dominazione, Squartamento. L'ira in eccesso va in Sfondamento o Spaccarmatura, poi Azzoppamento. Ti ricorda Urlo di Battaglia, Ira Sanguinaria, Assalto Eroico o Fendente per smaltire l'ira, Colpi Ampi, Desiderio di Morte, Avventatezza e le interruzioni. Il tempismo di Contusione, il cambio di postura e Furia del Berserker restano a te."
L["rm.tbc.warrior.protection.icyveins.Name"] = "Difensore (Icy Veins)"
L["rm.tbc.warrior.protection.icyveins.Description"] = "Livelli 10–70, scelta mentre sei in Postura Difensiva, seguendo Icy Veins. Colpo di Scudo, Rivincita, poi Sfondamento o Spaccarmatura, con Squartamento all'inizio del combattimento finché non hai appreso Colpo di Scudo. Contro i gruppi: Schianto del Tuono, e Urlo Demoralizzante contro le élite. Scudo Saldo viene ricordato ogni volta che il tuo bersaglio ti attacca e porti uno scudo. Provocazioni e altre utilità restano a te. Un'alternativa alla rotazione integrata consigliata da difensore di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.tbc.warrior.protection.wowhead.Name"] = "Difensore (Wowhead)"
L["rm.tbc.warrior.protection.wowhead.Description"] = "Livelli 10–70, scelta mentre sei in Postura Difensiva. Colpo di Scudo, Rivincita, Schianto del Tuono e Urlo Demoralizzante mantenuti su élite e boss, poi Sfondamento o Spaccarmatura. Contro i gruppi: prima Schianto del Tuono e Urlo Demoralizzante. Ti ricorda Scudo Saldo (con uno scudo equipaggiato) contro i boss e i nemici di livello superiore, Assalto Eroico o Fendente, Urlo di Battaglia, Ira Sanguinaria, Botta di Scudo e, in emergenza, Ultima Difesa e Muro di Scudi. Provocazioni e altre utilità restano a te."
